                 //                    }
                 //                ],
                 //                "exchangeId": "301",
                 //                "symbol": "ETHUSDT",
                 //                "symbolName": "ETHUSDT",
                 //                "status": "TRADING",
                 //                "baseAsset": "ETH",
                 //                "baseAssetName": "ETH",
                 //                "baseAssetPrecision": "0.0001",
                 //                "quoteAsset": "USDT",
